//go:build jqinterest_exhaustive

package jqinterest

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// TestCorpusSubset_IsCurrent recomputes the stratified subset from the whole
// corpus and fails when the committed testdata/corpus_subset.json differs:
// a corpus or analysis change can create a stratum the default path no
// longer covers. Regenerate with
//
//	JQINTEREST_UPDATE_SUBSET=1 go test -tags 'unit integration jqinterest_exhaustive' -run TestCorpusSubset_IsCurrent ./internal/cache/jqinterest
//
// The pinned chains are kept from the committed file.
func TestCorpusSubset_IsCurrent(t *testing.T) {
	_, chains := loadCorpus(t)
	var committed corpusSubset
	got, err := os.ReadFile(subsetFile)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(got, &committed); err != nil {
		t.Fatal(err)
	}
	sub, strata := stratifiedSubset(chains, committed.Pinned)
	names := make([]string, len(sub))
	for i, nc := range sub {
		names[i] = nc.name
	}
	t.Logf("stratified subset: %d of %d chains, %d strata, %d pinned", len(sub), len(chains), strata, len(committed.Pinned))
	want := corpusSubset{
		Note: "Generated by TestCorpusSubset_IsCurrent (-tags jqinterest_exhaustive, JQINTEREST_UPDATE_SUBSET=1). " +
			"One representative of every stratum of corpusStrata, every membership-claiming chain, and the pinned chains (#663).",
		Pinned: committed.Pinned,
		Chains: names,
	}
	b, _ := json.MarshalIndent(want, "", "  ")
	b = append(b, '\n')
	if os.Getenv("JQINTEREST_UPDATE_SUBSET") != "" {
		if err := os.WriteFile(subsetFile, b, 0o600); err != nil {
			t.Fatal(err)
		}
		t.Logf("wrote %s", subsetFile)
		return
	}
	if strings.TrimSpace(string(got)) != strings.TrimSpace(string(b)) {
		t.Fatalf("%s is stale: the corpus or the analysis changed its strata; regenerate it (see the comment above)", subsetFile)
	}
}
